// What a package reads from `process`: the program's state, however the
// package runs.
export function argv() {
  return process.argv.slice(2);
}
export function argvLength() {
  return process.argv.length;
}
export function env(name) {
  return process.env[name];
}
export function setEnv(name, value) {
  process.env[name] = value;
}
export function cwd() {
  return process.cwd();
}
export function chdir(directory) {
  process.chdir(directory);
}
export function pid() {
  return process.pid;
}
export function platform() {
  return process.platform;
}
export function isTTY() {
  return [process.stdout.isTTY === true, process.stderr.isTTY === true];
}
export function exitCode() {
  return process.exitCode;
}
export function setExitCode(code) {
  process.exitCode = code;
}
export function columns() {
  return process.stdout.columns;
}
